CREATE VIEW "FIBEN_L15"."CONVERSIONOFSTOCK" AS SELECT t."CONVERSIONOFSTOCKID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."CONVERSIONOFSTOCK" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."CONVERSIONOFSTOCKID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."CONVERSIONOFSTOCKID";
CREATE VIEW "FIBEN_L15"."CORPORATION" AS SELECT t."CORPORATIONID", t."ISCLASSIFIEDBY", t."ISDOMICILEDIN", t."HASTICKERSYMBOL", t."HASLEGALNAME" FROM "FIBEN"."CORPORATION" t LEFT JOIN "FIBEN"."AUTONOMOUSAGENT" a0 ON a0."AUTONOMOUSAGENTID" = t."CORPORATIONID";
CREATE VIEW "FIBEN_L15"."COSTMETHODINVESTMENTS" AS SELECT t."COSTMETHODINVESTMENTSID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."COSTMETHODINVESTMENTS" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."COSTMETHODINVESTMENTSID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."COSTMETHODINVESTMENTSID";
CREATE VIEW "FIBEN_L15"."COSTSOFRETIREMENTPLANS" AS SELECT t."COSTSOFRETIREMENTPLANSID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."COSTSOFRETIREMENTPLANS" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."COSTSOFRETIREMENTPLANSID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."COSTSOFRETIREMENTPLANSID";
CREATE VIEW "FIBEN_L15"."COUNTRY" AS SELECT t."COUNTRYID", t."HASNAME", t."HASNUMERICCOUNTRYCODE" FROM "FIBEN"."COUNTRY" t ;
CREATE VIEW "FIBEN_L15"."CURRENCY" AS SELECT t."CURRENCYID", t."HASNUMERICCODE", t."HASCURRENCYNAME", t."HASMINORUNIT" FROM "FIBEN"."CURRENCY" t ;
CREATE VIEW "FIBEN_L15"."DEBT" AS SELECT t."DEBTID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DEBT" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DEBTID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DEBTID";
CREATE VIEW "FIBEN_L15"."DEBTCONVERSION" AS SELECT t."DEBTCONVERSIONID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DEBTCONVERSION" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DEBTCONVERSIONID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DEBTCONVERSIONID";
CREATE VIEW "FIBEN_L15"."DEFERREDTAXASSETSANDLIABILITIES" AS SELECT t."DEFERREDTAXASSETSANDLIABILITIESID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DEFERREDTAXASSETSANDLIABILITIES" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DEFERREDTAXASSETSANDLIABILITIESID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DEFERREDTAXASSETSANDLIABILITIESID";
CREATE VIEW "FIBEN_L15"."DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSS" AS SELECT t."DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSSID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSS" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSSID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSSID";
CREATE VIEW "FIBEN_L15"."DERIVATIVE" AS SELECT t."DERIVATIVEID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DERIVATIVE" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DERIVATIVEID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DERIVATIVEID";
CREATE VIEW "FIBEN_L15"."DISCLOSURE" AS SELECT t."DISCLOSUREID", t."HASMETRICYEARCALENDAR", t."HASMETRICSTARTDATE", t."HASDOCUMENTTYPE", t."HASMETRICENDQUARTER", t."HASUNIT", t."APPLICABLEPERIOD", t."HASUNIQUEIDENTIFIER", t."HASMETRICENDDATE", t."ISCOMPUTED", t."HASMETRICVALUE", t."HASMETRICYEARFISCAL", t."HASURL", t."HASMETRICCONTEXTDIMENSIONS", t."HASMETRICSTARTQUARTER", a0."ISMEMBEROF", d.SUBCLASSES, d."HASNAME" FROM "FIBEN"."DISCLOSURE" t LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a0 ON a0."ELEMENTSOFFINANCIALREPORTID" = t."DISCLOSUREID" LEFT JOIN (SELECT __ID, string_agg(__CLS, ',' ORDER BY __CLS) AS SUBCLASSES, max("HASNAME") AS "HASNAME" FROM (SELECT "ACCOUNTSPAYABLEANDACCRUEDLIABILITIESID" AS __ID, 'AccountsPayableAndAccruedLiabilities' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ACCOUNTSPAYABLEANDACCRUEDLIABILITIES" UNION ALL SELECT "ACCOUNTSPAYABLEDETAILSID" AS __ID, 'AccountsPayableDetails' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ACCOUNTSPAYABLEDETAILS" UNION ALL SELECT "ACCRUEDLIABILITIESID" AS __ID, 'AccruedLiabilities' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ACCRUEDLIABILITIES" UNION ALL SELECT "ACCUMULATEDOTHERCOMPREHENSIVEINCOMELOSSID" AS __ID, 'AccumulatedOtherComprehensiveIncomeLoss' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ACCUMULATEDOTHERCOMPREHENSIVEINCOMELOSS" UNION ALL SELECT "ALLOWANCEFORCREDITLOSSESID" AS __ID, 'AllowanceForCreditLosses' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ALLOWANCEFORCREDITLOSSES" UNION ALL SELECT "ANTIDILUTIVESECURITIESEXCLUDEDFROMCOMPUTATIONOFEARNINGSPERSHAREID" AS __ID, 'AntidilutiveSecuritiesExcludedFromComputationOfEarningsPerShare' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ANTIDILUTIVESECURITIESEXCLUDEDFROMCOMPUTATIONOFEARNINGSPERSHARE" UNION ALL SELECT "ASSETIMPAIRMENTCHARGESID" AS __ID, 'AssetImpairmentCharges' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ASSETIMPAIRMENTCHARGES" UNION ALL SELECT "ASSETRETIREMENTOBLIGATIONDISCLOSUREID" AS __ID, 'AssetRetirementObligationDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ASSETRETIREMENTOBLIGATIONDISCLOSURE" UNION ALL SELECT "AVAILABLEFORSALESECURITIESID" AS __ID, 'AvailableForSaleSecurities' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."AVAILABLEFORSALESECURITIES" UNION ALL SELECT "BUSINESSACQUISITIONINTEGRATIONRESTRUCTURINGANDOTHERRELATEDCOSTSID" AS __ID, 'BusinessAcquisitionIntegrationRestructuringAndOtherRelatedCosts' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."BUSINESSACQUISITIONINTEGRATIONRESTRUCTURINGANDOTHERRELATEDCOSTS" UNION ALL SELECT "BUSINESSACQUISITIONPROFORMAINFORMATIONID" AS __ID, 'BusinessAcquisitionProForMainFormation' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."BUSINESSACQUISITIONPROFORMAINFORMATION" UNION ALL SELECT "BUSINESSCOMBINATIONDISCLOSUREID" AS __ID, 'BusinessCombinationDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."BUSINESSCOMBINATIONDISCLOSURE" UNION ALL SELECT "CAPITALUNITSID" AS __ID, 'CapitalUnits' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CAPITALUNITS" UNION ALL SELECT "CASHANDCASHEQUIVALENTSID" AS __ID, 'CashAndCashEquivalents' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CASHANDCASHEQUIVALENTS" UNION ALL SELECT "CASHANDCASHEQUIVALENTSDISCLOSUREID" AS __ID, 'CashAndCashEquivalentsDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CASHANDCASHEQUIVALENTSDISCLOSURE" UNION ALL SELECT "CASHCASHEQUIVALENTSANDSHORTTERMINVESTMENTSID" AS __ID, 'CashCashEquivalentsAndShortTermInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CASHCASHEQUIVALENTSANDSHORTTERMINVESTMENTS" UNION ALL SELECT "CHANGEINACCOUNTINGESTIMATEID" AS __ID, 'ChangeInAccountingEstimate' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CHANGEINACCOUNTINGESTIMATE" UNION ALL SELECT "CHANGESINFAIRVALUEOFPLANASSETSID" AS __ID, 'ChangesInFairValueOfPlanAssets' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CHANGESINFAIRVALUEOFPLANASSETS" UNION ALL SELECT "COMMITMENTSCONTINGENCIESANDGUARANTEESID" AS __ID, 'CommitmentsContingenciesAndGuarantees' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."COMMITMENTSCONTINGENCIESANDGUARANTEES" UNION ALL SELECT "COMPREHENSIVEINCOMELOSSID" AS __ID, 'ComprehensiveIncomeLoss' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."COMPREHENSIVEINCOMELOSS" UNION ALL SELECT "CONVERSIONOFSTOCKID" AS __ID, 'ConversionOfStock' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."CONVERSIONOFSTOCK" UNION ALL SELECT "COSTMETHODINVESTMENTSID" AS __ID, 'CostMethodInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."COSTMETHODINVESTMENTS" UNION ALL SELECT "COSTSOFRETIREMENTPLANSID" AS __ID, 'CostsOfRetirementPlans' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."COSTSOFRETIREMENTPLANS" UNION ALL SELECT "DEBTID" AS __ID, 'Debt' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DEBT" UNION ALL SELECT "DEBTCONVERSIONID" AS __ID, 'DebtConversion' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DEBTCONVERSION" UNION ALL SELECT "DEFERREDTAXASSETSANDLIABILITIESID" AS __ID, 'DeferredTaxAssetsAndLiabilities' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DEFERREDTAXASSETSANDLIABILITIES" UNION ALL SELECT "DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSSID" AS __ID, 'DefinedBenefitPlanAmountsRecognizedInOtherComprehensiveIncomeLoss' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DEFINEDBENEFITPLANAMOUNTSRECOGNIZEDINOTHERCOMPREHENSIVEINCOMELOSS" UNION ALL SELECT "DERIVATIVEID" AS __ID, 'Derivative' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DERIVATIVE" UNION ALL SELECT "DIVIDENDPAYMENTRESTRICTIONSID" AS __ID, 'DividendPaymentRestrictions' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DIVIDENDPAYMENTRESTRICTIONS" UNION ALL SELECT "DIVIDENDSPAYABLEID" AS __ID, 'DividendsPayable' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DIVIDENDSPAYABLE" UNION ALL SELECT "EFFECTIVEINCOMETAXRATERECONCILIATIONID" AS __ID, 'EffectiveIncomeTaxRateReconciliation' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."EFFECTIVEINCOMETAXRATERECONCILIATION" UNION ALL SELECT "ENTITYLOCATIONID" AS __ID, 'EntityLocation' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ENTITYLOCATION" UNION ALL SELECT "EQUITYMETHODINVESTMENTSID" AS __ID, 'EquityMethodInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."EQUITYMETHODINVESTMENTS" UNION ALL SELECT "ERRORCORRECTIONSANDPRIORPERIODADJUSTMENTSID" AS __ID, 'ErrorCorrectionsAndPriorPeriodAdjustments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ERRORCORRECTIONSANDPRIORPERIODADJUSTMENTS" UNION ALL SELECT "EXTINGUISHMENTOFDEBTID" AS __ID, 'ExtinguishmentOfDebt' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."EXTINGUISHMENTOFDEBT" UNION ALL SELECT "EXTRAORDINARYITEMSID" AS __ID, 'ExtraordinaryItems' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."EXTRAORDINARYITEMS" UNION ALL SELECT "FINANCIALINSTRUMENTSSUBJECTTOMANDATORYREDEMPTIONID" AS __ID, 'FinancialInstrumentsSubjectToMandatoryRedemption' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCIALINSTRUMENTSSUBJECTTOMANDATORYREDEMPTION" UNION ALL SELECT "FINANCIALMETRICSID" AS __ID, 'FinancialMetrics' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCIALMETRICS" UNION ALL SELECT "FINANCINGRECEIVABLEALLOWANCEFORCREDITLOSSESID" AS __ID, 'FinancingReceivableAllowanceForCreditLosses' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCINGRECEIVABLEALLOWANCEFORCREDITLOSSES" UNION ALL SELECT "FINANCINGRECEIVABLECREDITQUALITYINDICATORSID" AS __ID, 'FinancingReceivableCreditQualityIndicators' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCINGRECEIVABLECREDITQUALITYINDICATORS" UNION ALL SELECT "FINANCINGRECEIVABLESID" AS __ID, 'FinancingReceivables' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCINGRECEIVABLES" UNION ALL SELECT "FINANCINGRECEIVABLESPASTDUEID" AS __ID, 'FinancingReceivablesPastDue' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCINGRECEIVABLESPASTDUE" UNION ALL SELECT "FINANCINGRECEIVABLETROUBLEDDEBTRESTRUCTURINGSID" AS __ID, 'FinancingReceivableTroubledDebtRestructurings' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FINANCINGRECEIVABLETROUBLEDDEBTRESTRUCTURINGS" UNION ALL SELECT "FOREIGNCURRENCYTRANSLATIONID" AS __ID, 'ForeignCurrencyTranslation' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FOREIGNCURRENCYTRANSLATION" UNION ALL SELECT "FORWARDCONTRACTINDEXEDTOISSUERSEQUITYID" AS __ID, 'ForwardContractIndexedToIssuersEquity' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FORWARDCONTRACTINDEXEDTOISSUERSEQUITY" UNION ALL SELECT "FRESHSTARTADJUSTMENTSID" AS __ID, 'FresHstArtAdjustments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."FRESHSTARTADJUSTMENTS" UNION ALL SELECT "GAINLOSSONINVESTMENTSID" AS __ID, 'GainLossOnInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."GAINLOSSONINVESTMENTS" UNION ALL SELECT "GOODWILLID" AS __ID, 'Goodwill' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."GOODWILL" UNION ALL SELECT "GUARANTEESID" AS __ID, 'Guarantees' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."GUARANTEES" UNION ALL SELECT "GUARANTOROBLIGATIONSID" AS __ID, 'GuarantorObligations' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."GUARANTOROBLIGATIONS" UNION ALL SELECT "HELDTOMATURITYSECURITIESID" AS __ID, 'HeldToMaturitySecurities' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."HELDTOMATURITYSECURITIES" UNION ALL SELECT "IMPAIREDFINANCINGRECEIVABLESID" AS __ID, 'ImpairedFinancingReceivables' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."IMPAIREDFINANCINGRECEIVABLES" UNION ALL SELECT "INCOMETAXCONTINGENCYID" AS __ID, 'IncomeTaxContingency' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."INCOMETAXCONTINGENCY" UNION ALL SELECT "INDEFINITELIVEDINTANGIBLEASSETSID" AS __ID, 'IndefiniteLivedIntangibleAssets' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."INDEFINITELIVEDINTANGIBLEASSETS" UNION ALL SELECT "INTANGIBLEASSETSANDGOODWILLID" AS __ID, 'IntangibleAssetsAndGoodwill' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."INTANGIBLEASSETSANDGOODWILL" UNION ALL SELECT "INTERESTANDOTHERINCOMEID" AS __ID, 'InterestAndOtherIncome' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."INTERESTANDOTHERINCOME" UNION ALL SELECT "INTERESTCOSTSINCURRE