S __ID, 'NewAccountingPronouncementEarlyAdoption' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."NEWACCOUNTINGPRONOUNCEMENTEARLYADOPTION" UNION ALL SELECT "NONCONTROLLINGINTERESTID" AS __ID, 'NoncontrollingInterest' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."NONCONTROLLINGINTEREST" UNION ALL SELECT "OPERATINGLOSSCARRYFORWARDSID" AS __ID, 'OperatingLossCarryForwards' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OPERATINGLOSSCARRYFORWARDS" UNION ALL SELECT "OTHERASSETSID" AS __ID, 'OtherAssets' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERASSETS" UNION ALL SELECT "OTHERASSETSANDOTHERLIABILITIESID" AS __ID, 'OtherAssetsAndOtherLiabilities' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERASSETSANDOTHERLIABILITIES" UNION ALL SELECT "OTHERASSETSDISCLOSUREID" AS __ID, 'OtherAssetsDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERASSETSDISCLOSURE" UNION ALL SELECT "OTHERASSETSNONCURRENTID" AS __ID, 'OtherAssetsNoncurrent' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERASSETSNONCURRENT" UNION ALL SELECT "OTHERLIABILITIESDISCLOSUREID" AS __ID, 'OtherLiabilitiesDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERLIABILITIESDISCLOSURE" UNION ALL SELECT "OTHERNONOPERATINGINCOMEEXPENSEID" AS __ID, 'OtherNonOperatingIncomeExpense' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERNONOPERATINGINCOMEEXPENSE" UNION ALL SELECT "OTHEROWNERSHIPINTERESTSID" AS __ID, 'OtherOwnershipInterests' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHEROWNERSHIPINTERESTS" UNION ALL SELECT "OTHERTHANTEMPORARYIMPAIRMENTCREDITLOSSESRECOGNIZEDINEARNINGSID" AS __ID, 'OtherThanTemporaryImpairmentCreditLossesRecognizedInEarnings' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."OTHERTHANTEMPORARYIMPAIRMENTCREDITLOSSESRECOGNIZEDINEARNINGS" UNION ALL SELECT "PREFERREDSTOCKID" AS __ID, 'PreferredStock' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PREFERREDSTOCK" UNION ALL SELECT "PRODUCTWARRANTYLIABILITYID" AS __ID, 'ProductWarrantyLiability' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PRODUCTWARRANTYLIABILITY" UNION ALL SELECT "PROPERTYMANAGEMENTFEEID" AS __ID, 'PropertyManagementFee' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PROPERTYMANAGEMENTFEE" UNION ALL SELECT "PROPERTYPLANTANDEQUIPMENTID" AS __ID, 'PropertyPlantAndEquipment' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PROPERTYPLANTANDEQUIPMENT" UNION ALL SELECT "PROPERTYPLANTANDEQUIPMENTINCOMESTATEMENTDISCLOSURESID" AS __ID, 'PropertyPlantAndEquipmentIncomeStatementDisclosures' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PROPERTYPLANTANDEQUIPMENTINCOMESTATEMENTDISCLOSURES" UNION ALL SELECT "PROPERTYPLANTANDEQUIPMENTUSEFULLIVESID" AS __ID, 'PropertyPlantAndEquipmentUseFullives' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PROPERTYPLANTANDEQUIPMENTUSEFULLIVES" UNION ALL SELECT "PROPERTYSUBJECTTOORAVAILABLEFOROPERATINGLEASEID" AS __ID, 'PropertySubjectToOrAvailableForOperatingLease' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."PROPERTYSUBJECTTOORAVAILABLEFOROPERATINGLEASE" UNION ALL SELECT "REALESTATEPROPERTIESID" AS __ID, 'RealEstateProperties' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."REALESTATEPROPERTIES" UNION ALL SELECT "REALIZEDGAINLOSSID" AS __ID, 'RealizedGainLoss' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."REALIZEDGAINLOSS" UNION ALL SELECT "REALIZEDGAINLOSSONINVESTMENTSID" AS __ID, 'RealizedGainLossOnInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."REALIZEDGAINLOSSONINVESTMENTS" UNION ALL SELECT "RECONCILIATIONOFOPERATINGPROFITLOSSFROMSEGMENTSTOCONSOLIDATEDID" AS __ID, 'ReconciliationOfOperatingProfitLossFromSegmentsToConsolidated' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."RECONCILIATIONOFOPERATINGPROFITLOSSFROMSEGMENTSTOCONSOLIDATED" UNION ALL SELECT "RECORDEDUNCONDITIONALPURCHASEOBLIGATIONID" AS __ID, 'RecordedUnconditionalPurchaseObligation' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."RECORDEDUNCONDITIONALPURCHASEOBLIGATION" UNION ALL SELECT "REDEEMABLENONCONTROLLINGINTERESTID" AS __ID, 'RedeemableNoncontrollingInterest' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."REDEEMABLENONCONTROLLINGINTEREST" UNION ALL SELECT "RELATEDPARTYTRANSACTIONSBYRELATEDPARTYID" AS __ID, 'RelatedPartyTransactionsByRelatedParty' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."RELATEDPARTYTRANSACTIONSBYRELATEDPARTY" UNION ALL SELECT "RENTEXPENSEID" AS __ID, 'RentExpense' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."RENTEXPENSE" UNION ALL SELECT "RESTRICTEDCASHANDCASHEQUIVALENTSID" AS __ID, 'RestrictedCashAndCashEquivalents' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."RESTRICTEDCASHANDCASHEQUIVALENTS" UNION ALL SELECT "RESTRUCTURINGANDRELATEDCOSTSID" AS __ID, 'RestructuringAndRelatedCosts' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."RESTRUCTURINGANDRELATEDCOSTS" UNION ALL SELECT "SALELEASEBACKTRANSACTIONID" AS __ID, 'SaleLeaseBackTransaction' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SALELEASEBACKTRANSACTION" UNION ALL SELECT "SHAREBASEDCOMPENSATIONACTIVITYID" AS __ID, 'ShareBasedCompensationActivity' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONACTIVITY" UNION ALL SELECT "SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSGRANTSINPERIODGRANTDATEINTRINSICVALUEID" AS __ID, 'ShareBasedCompensationArrangementByShareBasedPaymentAwardOptionsGrantsInPeriodGrantDateIntrinsicValue' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSGRANTSINPERIODGRANTDATEINTRINSICVALUE" UNION ALL SELECT "SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSGRANTSINPERIODWEIGHTEDAVERAGEGRANTDATEFAIRVALUEID" AS __ID, 'ShareBasedCompensationArrangementByShareBasedPaymentAwardOptionsGrantsInPeriodWeightedAverageGrantDateFairValue' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSGRANTSINPERIODWEIGHTEDAVERAGEGRANTDATEFAIRVALUE" UNION ALL SELECT "SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSVESTEDANDEXPECTEDTOVESTEXERCISABLEID" AS __ID, 'ShareBasedCompensationArrangementByShareBasedPaymentAwardOptionsVestedAndExpectedToVestExercisable' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSVESTEDANDEXPECTEDTOVESTEXERCISABLE" UNION ALL SELECT "SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSVESTEDANDEXPECTEDTOVESTOUTSTANDINGANDEXERCISABLEID" AS __ID, 'ShareBasedCompensationArrangementByShareBasedPaymentAwardOptionsVestedAndExpectedToVestOutstandingAndExercisable' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDOPTIONSVESTEDANDEXPECTEDTOVESTOUTSTANDINGANDEXERCISABLE" UNION ALL SELECT "SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDRESTRICTEDSTOCKUNITSVESTEDANDEXPECTEDTOVESTID" AS __ID, 'ShareBasedCompensationArrangementByShareBasedPaymentAwardRestrictedStockUnitsVestedAndExpectedToVest' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONARRANGEMENTBYSHAREBASEDPAYMENTAWARDRESTRICTEDSTOCKUNITSVESTEDANDEXPECTEDTOVEST" UNION ALL SELECT "SHAREBASEDCOMPENSATIONRESTRICTEDSTOCKUNITSAWARDACTIVITYID" AS __ID, 'ShareBasedCompensationRestrictedStockUnitsAwardActivity' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHAREBASEDCOMPENSATIONRESTRICTEDSTOCKUNITSAWARDACTIVITY" UNION ALL SELECT "SHORTTERMDEBTID" AS __ID, 'ShortTermDebt' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SHORTTERMDEBT" UNION ALL SELECT "STOCKHOLDERSEQUITYID" AS __ID, 'StockholdersEquity' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."STOCKHOLDERSEQUITY" UNION ALL SELECT "SUBSEQUENTEVENTSID" AS __ID, 'SubsequentEvents' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."SUBSEQUENTEVENTS" UNION ALL SELECT "TAXCREDITCARRYFORWARDID" AS __ID, 'TaxCreditCarryForward' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."TAXCREDITCARRYFORWARD" UNION ALL SELECT "TRADINGSECURITIESANDOTHERTRADINGASSETSID" AS __ID, 'TradingSecuritiesAndOtherTradingAssets' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."TRADINGSECURITIESANDOTHERTRADINGASSETS" UNION ALL SELECT "TREASURYSTOCKID" AS __ID, 'TreasuryStock' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."TREASURYSTOCK" UNION ALL SELECT "UNREALIZEDGAINLOSSONINVESTMENTSID" AS __ID, 'UnrealizedGainLossOnInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."UNREALIZEDGAINLOSSONINVESTMENTS" UNION ALL SELECT "UNREALIZEDLOSSONINVESTMENTSID" AS __ID, 'UnrealizedLossOnInvestments' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."UNREALIZEDLOSSONINVESTMENTS" UNION ALL SELECT "UNRECORDEDUNCONDITIONALPURCHASEOBLIGATIONID" AS __ID, 'UnrecordedUnconditionalPurchaseObligation' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."UNRECORDEDUNCONDITIONALPURCHASEOBLIGATION" UNION ALL SELECT "UNRECORDEDUNCONDITIONALPURCHASEOBLIGATIONSDISCLOSUREID" AS __ID, 'UnrecordedUnconditionalPurchaseObligationsDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."UNRECORDEDUNCONDITIONALPURCHASEOBLIGATIONSDISCLOSURE" UNION ALL SELECT "VALUATIONALLOWANCEID" AS __ID, 'ValuationAllowance' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."VALUATIONALLOWANCE" UNION ALL SELECT "VALUATIONANDQUALIFYINGACCOUNTSDISCLOSUREID" AS __ID, 'ValuationAndQualifyingAccountsDisclosure' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."VALUATIONANDQUALIFYINGACCOUNTSDISCLOSURE" UNION ALL SELECT "WEIGHTEDAVERAGENUMBEROFSHARESID" AS __ID, 'WeightedAverageNumberOfShares' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."WEIGHTEDAVERAGENUMBEROFSHARES") GROUP BY __ID) d ON d.__ID = t."DISCLOSUREID";
CREATE VIEW "FIBEN_L15"."DISTRIBUTIONTOOWNER" AS SELECT t."DISTRIBUTIONTOOWNERID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DISTRIBUTIONTOOWNER" t LEFT JOIN "FIBEN"."ELEMENTOFFINANCIALSTATEMENT" a0 ON a0."ELEMENTOFFINANCIALSTATEMENTID" = t."DISTRIBUTIONTOOWNERID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DISTRIBUTIONTOOWNERID";
CREATE VIEW "FIBEN_L15"."DIVIDENDPAYMENTRESTRICTIONS" AS SELECT t."DIVIDENDPAYMENTRESTRICTIONSID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DIVIDENDPAYMENTRESTRICTIONS" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DIVIDENDPAYMENTRESTRICTIONSID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DIVIDENDPAYMENTRESTRICTIONSID";
CREATE VIEW "FIBEN_L15"."DIVIDENDSPAYABLE" AS SELECT t."DIVIDENDSPAYABLEID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."DIVIDENDSPAYABLE" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."DIVIDENDSPAYABLEID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."DIVIDENDSPAYABLEID";
CREATE VIEW "FIBEN_L15"."EFFECTIVEINCOMETAXRATERECONCILIATION" AS SELECT t."EFFECTIVEINCOMETAXRATERECONCILIATIONID", t."HASNAME", a0."HASMETRICYEARCALENDAR", a0."HASMETRICSTARTDATE", a0."HASDOCUMENTTYPE", a0."HASMETRICENDQUARTER", a0."HASUNIT", a0."APPLICABLEPERIOD", a0."HASUNIQUEIDENTIFIER", a0."HASMETRICENDDATE", a0."ISCOMPUTED", a0."HASMETRICVALUE", a0."HASMETRICYEARFISCAL", a0."HASURL", a0."HASMETRICCONTEXTDIMENSIONS", a0."HASMETRICSTARTQUARTER", a1."ISMEMBEROF" FROM "FIBEN"."EFFECTIVEINCOMETAXRATERECONCILIATION" t LEFT JOIN "FIBEN"."DISCLOSURE" a0 ON a0."DISCLOSUREID" = t."EFFECTIVEINCOMETAXRATERECONCILIATIONID" LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a1 ON a1."ELEMENTSOFFINANCIALREPORTID" = t."EFFECTIVEINCOMETAXRATERECONCILIATIONID";
CREATE VIEW "FIBEN_L15"."ELEMENTOFFINANCIALSTATEMENT" AS SELECT t."ELEMENTOFFINANCIALSTATEMENTID", t."HASMETRICYEARCALENDAR", t."HASMETRICSTARTDATE", t."HASDOCUMENTTYPE", t."HASMETRICENDQUARTER", t."HASUNIT", t."APPLICABLEPERIOD", t."HASUNIQUEIDENTIFIER", t."HASMETRICENDDATE", t."ISCOMPUTED", t."HASMETRICVALUE", t."HASMETRICYEARFISCAL", t."HASURL", t."HASMETRICCONTEXTDIMENSIONS", t."HASMETRICSTARTQUARTER", a0."ISMEMBEROF", d.SUBCLASSES, d."HASNAME" FROM "FIBEN"."ELEMENTOFFINANCIALSTATEMENT" t LEFT JOIN "FIBEN"."ELEMENTSOFFINANCIALREPORT" a0 ON a0."ELEMENTSOFFINANCIALREPORTID" = t."ELEMENTOFFINANCIALSTATEMENTID" LEFT JOIN (SELECT __ID, string_agg(__CLS, ',' ORDER BY __CLS) AS SUBCLASSES, max("HASNAME") AS "HASNAME" FROM (SELECT "ASSETID" AS __ID, 'Asset' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."ASSET" UNION ALL SELECT "COMPREHENSIVEINCOMEID" AS __ID, 'ComprehensiveIncome' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."COMPREHENSIVEINCOME" UNION ALL SELECT "DISTRIBUTIONTOOWNERID" AS __ID, 'DistributionToOwner' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."DISTRIBUTIONTOOWNER" UNION ALL SELECT "EQUITYID" AS __ID, 'Equity' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."EQUITY" UNION ALL SELECT "EXPENSEID" AS __ID, 'Expense' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."EXPENSE" UNION ALL SELECT "LIABILITYID" AS __ID, 'Liability' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."LIABILITY" UNION ALL SELECT "LOSSID" AS __ID, 'Loss' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."LOSS" UNION ALL SELECT "REVENUEID" AS __ID, 'Revenue' AS __CLS, "HASNAME" AS "HASNAME" FROM "FIBEN"."REVENUE") GROUP BY __ID) d ON d.__ID = t."ELEMENTOFFINANCIALSTATEMENTID";
