CREATE VIEW "FIBEN_L15"."FINANCIALINSTRUMENT" AS SELECT t."FINANCIALINSTRUMENTID", t."ISTRANSFERABLE", d.SUBCLASSES, d."HASLASTTRADEDVALUE", d."HASLEGALNAME", d."HASLISTINGDATE", d."HASTICKERSYMBOL", d."ISPROVIDEDBY", d."ISTRADEDON" FROM "FIBEN"."FINANCIALINSTRUMENT" t LEFT JOIN (SELECT __ID, string_agg(__CLS, ',' ORDER BY __CLS) AS SUBCLASSES, max("HASLASTTRADEDVALUE") AS "HASLASTTRADEDVALUE", max("HASLEGALNAME") AS "HASLEGALNAME", max("HASLISTINGDATE") AS "HASLISTINGDATE", max("HASTICKERSYMBOL") AS "HASTICKERSYMBOL", max("ISPROVIDEDBY") AS "ISPROVIDEDBY", max("ISTRADEDON") AS "ISTRADEDON" FROM (SELECT "LISTEDSECURITYID" AS __ID, 'ListedSecurity' AS __CLS, "HASLASTTRADEDVALUE" AS "HASLASTTRADEDVALUE", "HASLEGALNAME" AS "HASLEGALNAME", "HASLISTINGDATE" AS "HASLISTINGDATE", "HASTICKERSYMBOL" AS "HASTICKERSYMBOL", NULL AS "ISPROVIDEDBY", NULL AS "ISTRADEDON" FROM "FIBEN"."LISTEDSECURITY" UNION ALL SELECT "SECURITYID" AS __ID, 'Security' AS __CLS, NULL AS "HASLASTTRADEDVALUE", NULL AS "HASLEGALNAME", NULL AS "HASLISTINGDATE", NULL AS "HASTICKERSYMBOL", "ISPROVIDEDBY" AS "ISPROVIDEDBY", "ISTRADEDON" AS "ISTRADEDON" FROM "FIBEN"."SECURITY") GROUP BY __ID) d ON d.__ID = t."FINANCIALINSTRUMENTID";
