CREATE VIEW "FIBEN_L15"."SECURITY" AS SELECT t."SECURITYID", t."ISTRADEDON", t."ISPROVIDEDBY", a0."ISTRANSFERABLE", d.SUBCLASSES, d."HASLASTTRADEDVALUE", d."HASLEGALNAME", d."HASLISTINGDATE", d."HASTICKERSYMBOL" FROM "FIBEN"."SECURITY" t LEFT JOIN "FIBEN"."FINANCIALINSTRUMENT" a0 ON a0."FINANCIALINSTRUMENTID" = t."SECURITYID" LEFT JOIN (SELECT __ID, string_agg(__CLS, ',' ORDER BY __CLS) AS SUBCLASSES, max("HASLASTTRADEDVALUE") AS "HASLASTTRADEDVALUE", max("HASLEGALNAME") AS "HASLEGALNAME", max("HASLISTINGDATE") AS "HASLISTINGDATE", max("HASTICKERSYMBOL") AS "HASTICKERSYMBOL" FROM (SELECT "LISTEDSECURITYID" AS __ID, 'ListedSecurity' AS __CLS, "HASLASTTRADEDVALUE" AS "HASLASTTRADEDVALUE", "HASLEGALNAME" AS "HASLEGALNAME", "HASLISTINGDATE" AS "HASLISTINGDATE", "HASTICKERSYMBOL" AS "HASTICKERSYMBOL" FROM "FIBEN"."LISTEDSECURITY") GROUP BY __ID) d ON d.__ID = t."SECURITYID";
